<?php

declare(strict_types=1);

/**
 * BoardSim deployment shim — the only PHP file the document root needs.
 *
 * The API's real front controller lives outside the document root, so this file
 * answers `/v1/...` by loading it from an absolute filesystem path. The document
 * root is an Apache boundary, not a PHP one: `require` is a filesystem read, so
 * code outside the docroot is perfectly loadable (subject to open_basedir).
 *
 * HOW THE POINTER WORKS
 *
 *   api/backend.php   a one-line file next to this one, generated by
 *                     bin/build-deploy.php and containing only a path:
 *
 *                         <?php return '/home/USER/boardsim-app';
 *
 *                     It holds no secret — only a filesystem path — and
 *                     public/.htaccess denies it over HTTP while `require` still
 *                     reads it. Nothing else in the document root knows where the
 *                     backend lives.
 *
 * If the pointer is absent or wrong, this file answers with a JSON error naming
 * every path it tried and the active open_basedir, because on a host with no
 * shell access that response is the diagnosis. Fail loudly, never with a blank
 * 500 and never with an HTML page: a browser that asked for JSON must be told,
 * in JSON, why it did not get any.
 */

$candidates = [];

$pointer = __DIR__ . '/backend.php';

if (is_file($pointer)) {
    $value = include $pointer;

    if (is_string($value) && trim($value) !== '') {
        $candidates['api/backend.php'] = $value;
    }
}

// A build writes the pointer next to this file (api/backend.php). Nothing else
// is needed: the document root knows no path except that file, so re-deploying
// cannot break it and no PHP here is ever hand-edited.

// Last resort: a backend that sits beside the document root. Harmless when it
// does not exist, and it saves a pointer file in the sibling-folder layout.
$candidates['sibling boardsim-app'] = dirname(__DIR__, 2) . '/boardsim-app';
$candidates['sibling boardsim-backend'] = dirname(__DIR__, 2) . '/boardsim-backend';

$tried = [];
$controller = null;

foreach ($candidates as $source => $root) {
    $root = rtrim((string) $root, "/\\");

    if ($root === '') {
        continue;
    }

    $file = $root . '/public/api/index.php';
    $found = is_file($file);

    $tried[] = ['source' => $source, 'root' => $root, 'controller_found' => $found];

    if ($found && $controller === null) {
        $controller = $file;
    }
}

if ($controller === null) {
    http_response_code(500);
    header('Content-Type: application/json; charset=utf-8');

    echo json_encode([
        'error' => is_file($pointer) ? 'BACKEND_NOT_FOUND' : 'SHIM_NOT_CONFIGURED',
        'message' => is_file($pointer)
            ? 'The backend is not at the path api/backend.php points to.'
            : 'api/backend.php is missing: this document root does not know where the backend is.',
        'fix' => 'Create or edit api/backend.php so it returns the absolute path of the '
            . 'backend directory (the one containing src/ and public/), e.g. '
            . "<?php return '/home/USER/boardsim-app';",
        'open_basedir' => ini_get('open_basedir') ?: null,
        'tried' => $tried,
    ], JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);

    return;
}

require $controller;
